// The status view (app/resource/status.js) as the page runs it: the real
// init (registered through lib/av), a stand-in EventSource, the page's own
// markup (generated by the Go test handlers/resource
// TestTransferStatusFixturesAreCurrent) and the server's own messages. The
// block's helpers have their own tests (transferStatus.test.js); these are
// about the wiring -- the stream it asks for, the two blocks it keeps in step,
// the player it listens to, the sticky bar it tells. It lives here and not
// next to status.js because webpack builds every .js under app/ as an entry.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { JSDOM } from 'jsdom';

const PAGE = readFileSync(new URL('./__fixtures__/transfer-status-page.html', import.meta.url), 'utf8');
const STATES = JSON.parse(readFileSync(new URL('./__fixtures__/transfer-status-states.json', import.meta.url), 'utf8'));
const S = Object.fromEntries(STATES.map((s) => [s.design, s.status]));
const RID = '08ada5a7a6183aae1e09d831df6748d566095a10';

const dom = new JSDOM(`<!doctype html><html lang="ru"><body>${PAGE}
<div id="content"><div id="file" data-status-file="/Sintel/Sintel.mkv"><video></video></div></div>
<div id="grace-cta" data-upsell-surface="grace" class="hidden"></div>
</body></html>`, { url: `https://webtor.io/ru/${RID}?file=%2FSintel%2FSintel.mkv&debug_status=caching&viewer=zero` });
global.window = dom.window;
global.document = dom.window.document;
global.CustomEvent = dom.window.CustomEvent;

const sources = [];
global.EventSource = class {
    static CLOSED = 2;
    constructor(url) { this.url = url; this.listeners = {}; this.closed = false; sources.push(this); }
    addEventListener(name, fn) { (this.listeners[name] ||= []).push(fn); }
    close() { this.closed = true; this.readyState = 2; }
    // Test side: what the server would send.
    message(status) { this.onmessage({ data: JSON.stringify(status) }); }
    ping() { (this.listeners.ping || []).forEach((fn) => fn({})); }
    // Refused (403): the browser closes it for good and says so once.
    refuse() { this.readyState = 2; this.onerror({}); }
};
// The tab's visibility (jsdom's own says "prerender" for good).
let visibility = 'visible';
Object.defineProperty(document, 'visibilityState', { configurable: true, get: () => visibility });
const setVisibility = (v) => {
    visibility = v;
    document.dispatchEvent(new window.Event('visibilitychange'));
};
const observed = [];
global.IntersectionObserver = class {
    constructor(cb) { this.cb = cb; observed.push(this); this.targets = []; }
    observe(el) { this.targets.push(el); }
    disconnect() { this.targets = []; }
};
const tracked = [];
window.umami = { track: (name, props) => tracked.push([name, props]) };
const events = [];
document.addEventListener('torrent-status', (e) => events.push(e.detail));

// lib/av registers the init against the element holding the script; the
// fixture's container is where get.html puts it.
const container = document.getElementById('torrent-status');
// What the view's renewal swaps in: the block as the server renders it.
const FRESH = container.innerHTML;
const script = document.createElement('script');
container.appendChild(script);
Object.defineProperty(document, 'currentScript', { configurable: true, get: () => script });
await import('../app/resource/status.js');
const [target, init, destroy] = window.av[0];
await init.call(target);
let source = sources[0];

const card = () => document.querySelector('#torrent-status [data-tx]');
const sticky = () => document.querySelector(`[data-status-mirror-for="${RID}"] [data-tx]`);
let video = document.querySelector('video');
const setVideo = (props) => {
    for (const [k, v] of Object.entries(props)) Object.defineProperty(video, k, { configurable: true, get: () => v });
};
setVideo({ paused: true, ended: false, seeking: false, readyState: 0 });
const fire = (name) => video.dispatchEvent(new window.Event(name));
// A new player element, as the next file (or a reload) brings: what the
// status keeps per element -- the grace popup's answer, the stall that spent
// it -- starts over with it.
const freshVideo = () => {
    const next = document.createElement('video');
    video.replaceWith(next);
    video = next;
    setVideo({ paused: true, ended: false, seeking: false, readyState: 0 });
};
// The player's buffer: its end, as hls.js leaves it; jsdom's own is always
// empty.
const buffered = (end) => setVideo({ buffered: { length: 1, end: () => end } });
const DAY = 24 * 60 * 60 * 1000;
// The plan box stays once up (lib/transferStatus.js keepBox), so a test about
// when one comes starts from a page view that has none: no seeders is where
// an up box goes.
const forgetBox = () => {
    source.message(S.noseed);
    assert.equal(card().querySelector('[data-tx-pbox]').hidden, true, 'fixture: no box up');
};

test('one stream, for the view and the viewer, on the file the page is on', () => {
    assert.equal(target.id, 'torrent-status');
    const u = new URL(source.url, 'https://webtor.io');
    assert.equal(u.pathname, `/ru/${RID}/status`);
    assert.equal(u.searchParams.get('_csrf'), 'csrf-token');
    assert.equal(u.searchParams.get('session'), '1', 'the view and the viewer\'s own link');
    assert.equal(u.searchParams.get('token'), 'status-token');
    assert.equal(u.searchParams.get('file'), '/Sintel/Sintel.mkv', 'the ETA prices this file');
    assert.equal(u.searchParams.get('debug_status'), 'caching', 'dev preview params ride along');
    assert.equal(u.searchParams.get('viewer'), 'zero');
    assert.equal(sources.length, 1);
});

test('the sticky bar gets the same block, once, with ids of its own', () => {
    assert.ok(sticky(), 'the copy is in the sticky bar');
    assert.equal(sticky().outerHTML.replaceAll('tx-details-sticky', 'tx-details').replaceAll('tx-bdesc-sticky', 'tx-bdesc'), card().outerHTML);
    assert.ok(document.getElementById('tx-details') && document.getElementById('tx-details-sticky'));
    // Each chain is described by its own block's badge.
    assert.equal(sticky().querySelector('[data-tx-toggle]').getAttribute('aria-describedby'), 'tx-bdesc-sticky');
    assert.equal(document.getElementById('tx-bdesc-sticky').closest('[data-tx]'), sticky());
});

test('a message is drawn into both blocks, and the sticky bar is told whether anything moves', () => {
    source.message(S.active);
    for (const block of [card(), sticky()]) {
        assert.equal(block.getAttribute('data-key'), 'active');
        const segs = block.querySelectorAll('[data-tx-seg]');
        assert.equal(segs[0].querySelector('.tx-spd').textContent, '38 Мбит/с');
        assert.equal(segs[1].querySelector('.tx-spd').textContent, '12 Мбит/с');
        assert.equal(block.querySelector('[data-tx-bar]').getAttribute('data-mode'), 'pieces');
    }
    assert.deepEqual(events.at(-1), { resourceId: RID, state: 'caching', moving: true });
    source.message(S.idle_torrent);
    assert.deepEqual(events.at(-1), { resourceId: RID, state: 'idle', moving: false });
});

test('long swarm gaps keep all three actors in the card and sticky chain while downloading or playing', (t) => {
    t.after(() => {
        setVideo({ paused: true, readyState: 0 });
        source.message(S.idle_torrent);
    });
    for (const [moving, gap, hls, completed] of [
        [S.active, S.caching_gap, S.caching_hls_gap, S.cached_flow],
        [S.vaulting, S.vaulting_gap, S.vaulting_hls_gap, S.vaulted],
    ]) {
        setVideo({ paused: true });
        fire('pause');
        for (const status of [moving, gap, moving]) {
            source.message(status);
            for (const block of [card(), sticky()]) {
                assert.equal(block.querySelectorAll('[data-tx-node]:not([hidden])').length, 3);
                assert.equal(block.querySelector('[data-tx-seg]').hasAttribute('data-moving'), status === moving);
            }
        }
        // The SSE update reads the player's current state. Avoid firing a
        // playback event that would retain activity for the next minute
        // in this shared fixture, after the test has restored the player.
        setVideo({ paused: false, readyState: 4 });
        source.message(hls);
        for (const block of [card(), sticky()]) {
            assert.equal(block.dataset.mode, 'chain');
            assert.equal(block.querySelectorAll('[data-tx-node]:not([hidden])').length, 3);
            assert.equal(block.querySelector('[data-tx-seg]').hasAttribute('data-moving'), false);
        }
        source.message(completed);
        for (const block of [card(), sticky()]) {
            assert.equal(block.querySelectorAll('[data-tx-node]:not([hidden])').length, 2);
            assert.equal(block.querySelector('[data-tx-node]').hidden, true);
        }
    }
});

test('at the cap with no player: the download box, its props saying where it is', () => {
    source.message(S.tier_dl);
    for (const [block, location] of [[card(), 'card'], [sticky(), 'sticky']]) {
        assert.equal(block.getAttribute('data-key'), 'tier_dl');
        const box = block.querySelector('[data-tx-pbox]');
        assert.equal(box.hidden, false);
        const a = box.querySelector('[data-tx-cta]');
        assert.equal(a.getAttribute('href'), '/ru/trial?from=status-bar');
        assert.equal(a.getAttribute('data-umami-event'), 'donate-status-bar');
        assert.equal(a.getAttribute('data-umami-event-location'), location);
        assert.equal(a.getAttribute('data-umami-event-ctx'), 'download');
    }
    assert.equal(events.at(-1).moving, true, 'the plan binds: worth keeping on screen');
});

const GRACE_KEYS = ['statusOverCap', 'statusStallSub', 'graceDurationSec', 'runOffset', 'graceCtaShown', 'graceCtaAnswered'];

// (Before any stall of this file's player: a stall colours the next minute.)
// Nothing is sold while the player is still inside its free grace window by
// movie time, however the server's verdict reads there; after a session seek
// past the window, the element's own clock counts from the seek point, and
// the offset says where it is. Past it, the popup the viewer answered has
// just told them of the cap: nothing either, until they hit it.
test('a file over the cap playing: nothing inside the grace window, nothing past it once the popup is answered', (t) => {
    t.after(() => {
        for (const k of GRACE_KEYS) delete video.dataset[k];
        setVideo({ paused: true, currentTime: 0 });
        fire('pause');
    });
    forgetBox();
    const stallSub = 'Без подписки — до 5 Мбит/с, а файлу нужно 8,9 Мбит/с';
    video.dataset.statusStallSub = stallSub;
    video.dataset.statusOverCap = '';
    video.dataset.graceDurationSec = '1200';
    video.dataset.runOffset = '0';
    setVideo({ paused: false, ended: false, seeking: false, readyState: 4, currentTime: 1170 });
    fire('loadstart');
    fire('playing');
    source.message(S.tier_dl);
    for (const block of [card(), sticky()]) {
        assert.equal(block.getAttribute('data-key'), 'stream_ok', '19:30 of a 20-minute window: nothing sold');
        assert.equal(block.querySelector('[data-tx-pbox]').hidden, true);
        assert.equal(block.querySelector('[data-tx-hint]').hidden, true, 'and no "no stops" either');
    }
    // A session seek to 24:30: the element starts over at 0, the offset is
    // the seek's -- past the window, not 0:06 into it. The player put its
    // grace popup up at the click (data-grace-cta-shown) and the viewer
    // answered it "continue" (data-grace-cta-answered).
    video.dataset.runOffset = '1470';
    video.dataset.graceCtaShown = '';
    video.dataset.graceCtaAnswered = 'continue';
    setVideo({ currentTime: 6 });
    source.ping();
    for (const block of [card(), sticky()]) {
        assert.equal(block.getAttribute('data-key'), 'stream_over', 'past the window');
        assert.equal(block.querySelector('[data-tx-pbox]').hidden, true, 'answered: no box while it plays');
        assert.equal(block.querySelector('[data-tx-hint]').hidden, true, 'and no line');
    }
});

// No grace popup at all -- a paid tier, grace off: nobody has just told the
// viewer of the cap. The owner's report (2026-09-25): at the cap the video
// stalled and the block said "no stops". A file the stream job marked over
// the cap gets the stream box as soon as the server says it is due -- the
// player playing from its buffer, not yet stalled.
test('a file over the cap playing, no grace popup: the stream box once due', (t) => {
    freshVideo();
    t.after(() => {
        for (const k of GRACE_KEYS) delete video.dataset[k];
        setVideo({ paused: true, currentTime: 0 });
        fire('pause');
    });
    forgetBox();
    const stallSub = 'До 10 Мбит/с, а файлу нужно 12 Мбит/с';
    video.dataset.statusStallSub = stallSub;
    video.dataset.statusOverCap = '';
    setVideo({ paused: false, ended: false, seeking: false, readyState: 4, currentTime: 1500 });
    fire('loadstart');
    fire('playing');
    source.message(S.tier_dl);
    for (const block of [card(), sticky()]) {
        assert.equal(block.getAttribute('data-key'), 'stream_over');
        const box = block.querySelector('[data-tx-pbox]');
        assert.equal(box.hidden, false, 'the box, while the player still plays');
        assert.equal(box.querySelector('[data-tx-ps]').textContent, stallSub);
        assert.equal(box.querySelector('[data-tx-cta]').getAttribute('data-umami-event-state'), 'stream_over');
        assert.equal(box.querySelector('[data-tx-cta]').getAttribute('data-umami-event-ctx'), 'stream');
    }
    // The cap's first seconds again (the box not due by the server's
    // count): the box up stays, and nothing else stands under the bar.
    source.message(S.tier_fact);
    assert.equal(card().getAttribute('data-key'), 'stream_over');
    assert.equal(card().querySelector('[data-tx-pbox]').hidden, false, 'up: it stays');
    assert.equal(card().querySelector('[data-tx-hint]').hidden, true);
    // A page view that has had none: before the box is due, the pink link
    // and nothing under the bar.
    forgetBox();
    source.message(S.tier_fact);
    assert.equal(card().getAttribute('data-key'), 'stream_over');
    assert.equal(card().querySelector('[data-tx-pbox]').hidden, true);
    assert.equal(card().querySelector('[data-tx-hint]').hidden, true);
});

// The owner's flow (2026-09-26), end to end. The window ends on two clocks:
// the status reads the element's on every render, the player puts its grace
// popup up from a render effect a frame or more later (none while the tab
// is hidden). Between the two the popup is on its way (playerActivity
// graceOfferDue): no box -- one offer at a time -- and no line in its place
// either (keepBox, 2026-09-27: the line came and went with the popup, and
// the block grew and shrank twice). While the popup is up it is the offer:
// nothing under the bar. The viewer
// answers "continue at N Mbps", or closes it: they have just been told of
// the cap, so no box -- and no line, "no stops" being false for this file --
// until the player's first real stall; then the stream box, as at any
// capped stall, and it stays as for any file over the cap. (In Chrome the
// box came 0.5 s after the popup closed: thp binds on the segments past the
// window, so the server's box was due before the popup went.)
for (const [i, answer] of ['continue', 'dismiss'].entries()) {
    test(`a file over the cap crossing the grace window, the popup answered "${answer}": nothing until the first real stall, then the box`, (t) => {
        // Well before the other tests' clocks, a separate hour each: the
        // stall below colours a minute, and the tests share one status view.
        t.mock.timers.enable({ apis: ['Date'], now: Date.now() - (2 - i) * 60 * 60 * 1000 });
        freshVideo();
        forgetBox();
        const stallSub = 'Без подписки — до 5 Мбит/с, а файлу нужно 8,9 Мбит/с';
        const popup = document.getElementById('grace-cta');
        // The next tests share this player: put it back even if this one fails.
        t.after(() => {
            for (const k of GRACE_KEYS) delete video.dataset[k];
            popup.classList.add('hidden');
            setVideo({ paused: true, currentTime: 0 });
            fire('pause');
        });
        const box = (block) => block.querySelector('[data-tx-pbox]');
        const hint = (block) => block.querySelector('[data-tx-hint]');
        video.dataset.statusStallSub = stallSub;
        video.dataset.statusOverCap = '';
        video.dataset.graceDurationSec = '1200';
        video.dataset.runOffset = '0';
        setVideo({ paused: false, ended: false, seeking: false, readyState: 4, currentTime: 1199.98 });
        fire('loadstart');
        fire('playing');
        source.message(S.tier_dl);
        assert.equal(card().getAttribute('data-key'), 'stream_ok', 'inside the window');
        assert.equal(box(card()).hidden, true);
        // Crossed; the popup not up yet.
        setVideo({ currentTime: 1200.01 });
        source.ping();
        for (const block of [card(), sticky()]) {
            assert.equal(box(block).hidden, true, 'no box while the popup is on its way');
            assert.equal(hint(block).hidden, true, 'and no line that would go again with the popup');
        }
        // The popup up: it is the offer -- nothing under the bar.
        video.dataset.graceCtaShown = '';
        popup.classList.remove('hidden');
        source.ping();
        assert.equal(box(card()).hidden, true, 'popup open: no box');
        assert.equal(hint(card()).hidden, true, 'no line');
        // Answered (Player.jsx marks the element, then hides the popup).
        video.dataset.graceCtaAnswered = answer;
        popup.classList.add('hidden');
        source.ping();
        for (const block of [card(), sticky()]) {
            assert.equal(block.getAttribute('data-key'), 'stream_over');
            assert.equal(box(block).hidden, true, 'answered: no box at once');
            assert.equal(hint(block).hidden, true, 'and no line: not "no stops"');
        }
        // Playing on from the buffer, the server's box due all along.
        t.mock.timers.tick(30_000);
        setVideo({ currentTime: 1230 });
        fire('timeupdate');
        source.message(S.tier_dl);
        assert.equal(box(card()).hidden, true, '30 s on: still nothing');
        assert.equal(hint(card()).hidden, true);
        // A hiccup is not the cap.
        setVideo({ readyState: 2 });
        fire('waiting');
        t.mock.timers.tick(500);
        setVideo({ readyState: 4, currentTime: 1230.6 });
        fire('playing');
        source.ping();
        assert.equal(box(card()).hidden, true, 'a hiccup sells nothing');
        // The buffer runs out at the cap: a real stall.
        t.mock.timers.tick(20_000);
        setVideo({ readyState: 2, currentTime: 1250 });
        fire('waiting');
        t.mock.timers.tick(1500);
        source.ping();
        for (const block of [card(), sticky()]) {
            assert.equal(block.getAttribute('data-key'), 'stream_stall');
            assert.equal(box(block).hidden, false, 'the stall: the box');
            assert.equal(box(block).querySelector('[data-tx-ps]').textContent, stallSub);
        }
        // Playing again, past the stall's minute: the box stays, as for any
        // file over the cap -- the answer is spent.
        setVideo({ readyState: 4, currentTime: 1250.3 });
        fire('playing');
        t.mock.timers.tick(61_000);
        setVideo({ currentTime: 1311 });
        fire('timeupdate');
        source.ping();
        assert.equal(card().getAttribute('data-key'), 'stream_over');
        assert.equal(box(card()).hidden, false, 'after the stall: the box while it plays');
    });
}

// A file under the cap playing: no line at all (owner, 2026-09-26), where the
// fact used to say "no stops".
test('a file under the cap playing: no line, the link as it is', () => {
    forgetBox();
    video.dataset.statusFitsCap = '';
    setVideo({ paused: false, ended: false, seeking: false, readyState: 4 });
    fire('loadstart');
    fire('playing');
    source.message(S.tier_dl);
    assert.equal(card().getAttribute('data-key'), 'stream_ok');
    assert.equal(card().querySelector('[data-tx-pbox]').hidden, true);
    assert.equal(card().querySelector('[data-tx-hint]').hidden, true);
    assert.equal(card().querySelectorAll('[data-tx-seg]')[1].getAttribute('data-tone'), 'flow');
    delete video.dataset.statusFitsCap;
    setVideo({ paused: true });
    fire('pause');
});

test('the page\'s player decides the variant the moment it changes, not at the next message', (t) => {
    t.mock.timers.enable({ apis: ['Date'], now: Date.now() });
    forgetBox();
    setVideo({ paused: false, readyState: 4 });
    fire('playing');
    source.message(S.tier_dl);
    const button = card().querySelector('[data-tx-cta]');
    assert.equal(card().getAttribute('data-key'), 'stream_ok');
    assert.equal(card().querySelector('[data-tx-pbox]').hidden, true, 'smooth playback: no button');
    // The stream job's line rides on the player.
    video.dataset.statusStallSub = 'Без подписки — до 5 Мбит/с, а файлу нужно 8 Мбит/с';
    setVideo({ readyState: 1 });
    fire('waiting');
    assert.equal(card().getAttribute('data-key'), 'stream_ok', 'a wait that has not lasted sells nothing');
    t.mock.timers.tick(1500);
    source.ping();
    assert.equal(card().getAttribute('data-key'), 'stream_stall');
    const box = card().querySelector('[data-tx-pbox]');
    assert.equal(box.hidden, false);
    assert.equal(box.querySelector('[data-tx-ps]').textContent, 'Без подписки — до 5 Мбит/с, а файлу нужно 8 Мбит/с');
    assert.equal(card().querySelector('[data-tx-cta]'), button, 'the same button all along');
    // Playing on: the block says so at once; the box, once up, stays with
    // the stall's words.
    setVideo({ readyState: 4 });
    fire('playing');
    t.mock.timers.tick(61_000);
    source.ping();
    assert.equal(card().getAttribute('data-key'), 'stream_ok');
    assert.equal(box.hidden, false, 'up: it stays');
    assert.equal(box.querySelector('[data-tx-pt]').textContent, 'Видео подгружается медленнее, чем играет');
    assert.equal(box.querySelector('[data-tx-cta]').getAttribute('data-umami-event-state'), 'stream_stall', 'the box it is');
    assert.equal(card().querySelector('[data-tx-hint]').hidden, true, 'no "no stops" over it');
    delete video.dataset.statusStallSub;
});

// One offer at a time (the grace popup, the cap modal, the download nudge),
// without a jump: a box up keeps its place with its button down; none comes
// up while another offer is on screen, and no line stands in for it.
test('one offer at a time: the grace popup up, the status keeps its button down in place', () => {
    const popup = document.getElementById('grace-cta');
    const box = () => card().querySelector('[data-tx-pbox]');
    source.message(S.tier_dl);
    assert.equal(box().hidden, false);
    popup.classList.remove('hidden');
    source.ping();
    for (const block of [card(), sticky()]) {
        const b = block.querySelector('[data-tx-pbox]');
        assert.equal(b.hidden, false, 'the box stays');
        assert.ok(b.hasAttribute('data-quiet'), 'its button down');
        assert.equal(b.querySelector('[data-tx-cta]').hasAttribute('href'), false);
        assert.equal(block.querySelector('[data-tx-hint]').hidden, true, 'no line');
    }
    popup.classList.add('hidden');
    source.ping();
    assert.equal(box().hidden, false);
    assert.equal(box().hasAttribute('data-quiet'), false, 'the popup gone: the button back');
    assert.equal(box().querySelector('[data-tx-cta]').getAttribute('href'), '/ru/trial?from=status-bar');
    // None up: while the popup is on screen none comes, and nothing in its
    // place; it comes once the popup has gone.
    forgetBox();
    popup.classList.remove('hidden');
    source.message(S.tier_dl);
    assert.equal(box().hidden, true, 'another offer on screen: no box comes up');
    assert.equal(card().querySelector('[data-tx-hint]').hidden, true, 'and no line');
    popup.classList.add('hidden');
    source.ping();
    assert.equal(box().hidden, false, 'the popup gone: the box');
    assert.equal(box().hasAttribute('data-quiet'), false);
    setVideo({ paused: true, ended: true });
    fire('ended');
});

// The owner's rule (2026-09-27): once up, the box stays -- the cap over (the
// server sends no box any more), a pause, the download done, a gap in the
// data -- with its last words, in both blocks, the same nodes, never hidden.
// It goes where the offer would be false: no seeders, Vault failing.
test('the box stays once up: past the cap, in both blocks, with its last words; no seeders or a Vault failure take it', async () => {
    forgetBox();
    source.message(S.tier_dl);
    const blocks = [card(), sticky()];
    const boxes = blocks.map((b) => b.querySelector('[data-tx-pbox]'));
    const words = (b) => ['[data-tx-pt]', '[data-tx-ps]', '[data-tx-cta-label]', '[data-tx-pn]'].map((q) => b.querySelector(q).textContent)
        .concat(b.querySelector('[data-tx-cta]').getAttribute('href'), b.querySelector('[data-tx-cta]').getAttribute('data-umami-event-state'));
    const was = boxes.map(words);
    assert.ok(boxes.every((b) => !b.hidden), 'fixture: up');
    const records = [];
    const mo = new window.MutationObserver((r) => records.push(...r));
    for (const b of blocks) mo.observe(b, { childList: true, subtree: true, attributes: true, attributeFilter: ['hidden'] });
    for (const d of ['active', 'cached_flow', 'paused', 'cached', 'idle_torrent', 'status_unknown', 'vault_waiting', 'tier_fact', 'active']) {
        source.message(S[d]);
        boxes.forEach((b, i) => {
            assert.equal(b.hidden, false, `${d}: stays`);
            assert.deepEqual(words(b), was[i], `${d}: its words`);
        });
    }
    await Promise.resolve();
    mo.disconnect();
    const removed = records.filter((r) => r.type === 'childList').flatMap((r) => [...r.removedNodes]).filter((n) => n.nodeType === 1);
    assert.deepEqual(removed, [], 'nothing removed');
    const around = (el) => boxes.some((b) => b === el || b.contains(el) || el.contains(b));
    assert.deepEqual(records.filter((r) => r.type === 'attributes' && around(r.target)), [], 'the box and what holds it: never hidden');
    assert.equal(card().getAttribute('data-key'), 'active', 'the block says where it is');
    source.message(S.vault_failed);
    assert.ok(boxes.every((b) => b.hidden), 'Vault failing: gone');
    source.message(S.tier_dl);
    assert.ok(boxes.every((b) => !b.hidden), 'due again: up again');
    source.message(S.noseed);
    assert.ok(boxes.every((b) => b.hidden), 'no seeders: gone');
    source.message(S.active);
    assert.ok(boxes.every((b) => b.hidden), 'and not back with the next second');
});

