// HLS closes its request between two segments, and past the debounce the
// server's view no longer has the viewer -- the proxy counts nothing open.
// It sends the view with them at their last reading next to it, and while
// the page's own player plays that is what both blocks draw: no fall to the
// badge in every gap, the same nodes. Paused with the buffer full, nobody
// speaks for them: the page keeps the viewer with an explicit pause label,
// even if the buffer continues growing behind the paused picture.
test('the page\'s player playing through an HLS gap keeps the viewer on the chain', () => {
    // Before the film: an empty buffer, as a paused element reads it.
    buffered(0);
    source.ping();
    setVideo({ paused: false, ended: false, readyState: 4 });
    buffered(40);
    fire('playing');
    source.message(S.cached_flow);
    const nodes = Array.from(card().querySelectorAll('*'));
    source.message(S.hls_gap);
    for (const block of [card(), sticky()]) {
        assert.equal(block.getAttribute('data-mode'), 'chain');
        assert.equal(block.getAttribute('data-key'), 'cached_flow');
        assert.equal(block.querySelectorAll('[data-tx-node]')[2].hidden, false, 'the viewer on the chain');
        assert.equal(block.querySelectorAll('[data-tx-seg]')[1].querySelector('.tx-spd').textContent, '24\u00a0Мбит/с');
    }
    assert.equal(events.at(-1).moving, true, 'the sticky bar stays');
    const now = Array.from(card().querySelectorAll('*'));
    assert.ok(now.length === nodes.length && now.every((el, i) => el === nodes[i]), 'the same nodes');
    // Pause retains the viewer, including while the buffer keeps growing.
    setVideo({ paused: true });
    fire('pause');
    for (const block of [card(), sticky()]) {
        assert.equal(block.getAttribute('data-mode'), 'chain');
        assert.equal(block.querySelectorAll('[data-tx-node]')[2].hidden, false);
        assert.equal(block.querySelectorAll('[data-tx-seg]')[1].querySelector('.tx-spd').textContent, 'пауза');
    }
    assert.equal(events.at(-1).moving, true);
    buffered(48);
    source.ping();
    assert.equal(card().querySelectorAll('[data-tx-seg]')[1].querySelector('.tx-spd').textContent, 'пауза');
    // Playing again: back on the chain.
    setVideo({ paused: false });
    fire('playing');
    assert.equal(card().getAttribute('data-key'), 'cached_flow');
    // Before any measured segment, playback still owns viewer presence.
    source.message(S.cached);
    assert.equal(card().getAttribute('data-mode'), 'chain');
    assert.equal(card().querySelectorAll('[data-tx-seg]')[1].querySelector('.tx-spd').textContent, 'ждём данные');
    setVideo({ paused: true, ended: true, buffered: { length: 0, end: () => 0 } });
    fire('ended');
});

// The last reading bridges the gaps between HLS segments while the film
// plays from its buffer. Not while it waits for data: the number froze at
// the last segment, and "You 24 Mbps" with the wave running under a
// buffering pill says bytes flow that do not (a transcoder holding its
// segment answers nothing the proxy counts). The viewer waits.
test('the page\'s player stalled: the viewer waits, not the last reading with its wave', (t) => {
    // Before every later test's clock: a stall colours the minute after it.
    t.mock.timers.enable({ apis: ['Date'], now: Date.now() - 3 * 60 * 60 * 1000 });
    freshVideo();
    t.after(() => {
        setVideo({ paused: true, ended: true, readyState: 4 });
        fire('ended');
    });
    setVideo({ paused: false, ended: false, seeking: false, readyState: 4, currentTime: 300 });
    fire('loadstart');
    fire('playing');
    source.message(S.hls_gap);
    const seg = (block) => block.querySelectorAll('[data-tx-seg]')[1];
    assert.equal(seg(card()).querySelector('.tx-spd').textContent, '24 Мбит/с', 'fixture: the last reading while it plays');
    setVideo({ readyState: 1, currentTime: 300.2 });
    fire('waiting');
    t.mock.timers.tick(1500);
    source.message(S.hls_gap);
    for (const block of [card(), sticky()]) {
        assert.equal(block.querySelectorAll('[data-tx-node]')[2].hidden, false, 'still on the chain');
        assert.equal(seg(block).querySelector('.tx-spd').textContent, 'ждём данные');
        assert.equal(seg(block).hasAttribute('data-moving'), false, 'no wave');
    }
    setVideo({ readyState: 4, currentTime: 300.6 });
    fire('playing');
    source.message(S.hls_gap);
    assert.equal(seg(card()).querySelector('.tx-spd').textContent, '24 Мбит/с', 'playing again: the reading again');
});

